#!/bin/bash
# SPDX-License-Identifier: Apache-2.0
# build a *separate* traced Hyperion (cckd_read_trk track-access trace) into ~/herc-trace.
# The clean build (~/src/hyperion -> ~/herc-native) is not touched: the trace build uses a git
# worktree ~/src/hyperion-trace at the same pinned commit plus patches/0000-trace-trk.patch.
# Usage (on host): scripts/build-trace.sh            (logs: ~/webmvs/logs/build-trace-*.log)
#   If patches/0000-trace-trk.patch does not exist yet, it is generated by scripts/mk-trace-patch.py
#   and written to ~/webmvs/patches/ (copy it back to the local repo).
set -euo pipefail
PIN=ee86c4de066fcdb2ec898a157ff4c687c5f01ce2
SRC=$HOME/src/hyperion; WT=$HOME/src/hyperion-trace; PFX=$HOME/herc-trace
H=$HOME/webmvs; L=$H/logs; P=$H/patches/0000-trace-trk.patch
mkdir -p "$L" "$H/patches"
cd "$SRC"
if [ ! -d "$WT" ]; then git worktree add --detach "$WT" $PIN; fi
cd "$WT"
[ "$(git rev-parse HEAD)" = $PIN ] || { echo "worktree HEAD is not $PIN"; exit 1; }
git checkout -- . && git clean -fdq   # pristine tree at the pin
if [ ! -f "$P" ]; then
  python3 "$H/scripts/mk-trace-patch.py" cckddasd.c
  git diff -- cckddasd.c > "$P"
  git checkout -- cckddasd.c
fi
git apply --check "$P" && git apply "$P"
git diff --stat
./autogen.sh > "$L/build-trace-autogen.log" 2>&1
./configure --prefix="$PFX" > "$L/build-trace-configure.log" 2>&1
make -j16 > "$L/build-trace-make.log" 2>&1 || { tail -30 "$L/build-trace-make.log"; exit 1; }
grep -n "cckddasd.c.*warning\|cckddasd.c.*error" "$L/build-trace-make.log" || echo "no cckddasd.c warnings"
make install > "$L/build-trace-install.log" 2>&1
"$PFX/bin/hercules" --version 2>&1 | head -2
strings "$PFX/lib/libhercd.so" | grep -q HERC_TRK_TRACE || { echo "trace string not in libhercd.so"; exit 1; }
for f in "$HOME"/herc-native/lib/*.so; do strings "$f" | grep -q HERC_TRK_TRACE && { echo "clean build has the trace: $f"; exit 1; }; done
echo "build-trace: OK ($PFX)"
